-- PT103-S3-Q11. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT103-S3-Q11$batch04$ AND q.stimulus=$batch04$Lindsey has been judged to be a bad songwriter simply because her lyrics typically are disjointed and subjective. This judgment is ill founded, however, since the writings of many modern novelists typically are disjointed and subjective and yet these novelists are widely held to be good writers.$batch04$ AND q.prompt=$batch04$Which one of the following is an assumption on which the argument depends?$batch04$ AND q.correct_choice=$batch04$A$batch04$) THEN RAISE EXCEPTION 'Question changed: PT103-S3-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT103-S3-Q11$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT103-S3-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT103-S3-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$Judging Lindsey a bad songwriter because her lyrics are disjointed and subjective is ill-founded.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$Many modern novelists write in a disjointed, subjective way and are still considered good writers.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$This is an argument by analogy. It only works if novels and song lyrics are alike in the way that matters. Maybe that style works in a long novel but not in a short song.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A defender: the disjointed, subjective style works in songs the same way it does in novels.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT103-S3-Q11$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Negate it: this style does *not* have a comparable effect in novels and songs. Then the novelists tell us nothing about Lindsey's lyrics, and the analogy collapses.$batch04$), ($batch04$B$batch04$, $batch04$Whether some readers miss the subtleties of modern novels does not affect the comparison with Lindsey.$batch04$), ($batch04$C$batch04$, $batch04$Narrative structure is never discussed. The argument does not need Lindsey's lyrics to match other lyrics in structure.$batch04$), ($batch04$D$batch04$, $batch04$The argument does not compare novels and songs with other kinds of writing.$batch04$), ($batch04$E$batch04$, $batch04$The judgment being criticized is already about her lyrics. The author does not need lyrics to matter more than the music.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT103-S3-Q11$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
